import sys
from collections import deque

def findShortestPath(matrix):
    if not matrix or not matrix[0]:
        return -1

    rows = len(matrix)
    cols = len(matrix[0])

    # Create a grid to mark unsafe cells
    # A cell is unsafe if it's a mine (0) or adjacent to a mine
    unsafe = [[False] * cols for _ in range(rows)]

    directions = [(0, 1), (0, -1), (1, 0), (-1, 0)]

    for r in range(rows):
        for c in range(cols):
            if matrix[r][c] == 0:
                # Mark the mine itself as unsafe
                unsafe[r][c] = True
                # Mark all adjacent cells as unsafe
                for dr, dc in directions:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        unsafe[nr][nc] = True

    # BFS initialization
    queue = deque()
    visited = [[False] * cols for _ in range(rows)]

    # Add all safe cells in the first column to the queue
    for r in range(rows):
        if not unsafe[r][0]:
            queue.append((r, 0))
            visited[r][0] = True

    if not queue:
        return -1

    steps = 0

    while queue:
        level_size = len(queue)

        for _ in range(level_size):
            r, c = queue.popleft()

            # If we reached the last column, return steps + 1 (number of cells)
            if c == cols - 1:
                return steps + 1

            for dr, dc in directions:
                nr, nc = r + dr, c + dc

                if 0 <= nr < rows and 0 <= nc < cols: 
                    if not visited[nr][nc] and not unsafe[nr][nc]:
                        visited[nr][nc] = True
                        queue.append((nr, nc))

        steps += 1

    return -1

# Reading input from stdin
def main():
    data = sys.stdin.read().split()
    if not data:
        return

    iterator = iter(data)
    try:
        rows = int(next(iterator))
        cols = int(next(iterator))
    except StopIteration:
        return

    matrix = []
    for _ in range(rows):
        row = []
        for _ in range(cols):
            row.append(int(next(iterator)))
        matrix.append(row)

    result = findShortestPath(matrix)
    print(result)

if __name__ == "__main__":
    main()
